import React,{useEffect,useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,ArrowDownLeft,ArrowUpRight,ArrowLeftRight,CreditCard,Landmark,Users,Briefcase,WalletCards,Target,CalendarDays,FileText,Settings,Plus,Search,Trash2,Download,Upload,Menu,X,ChevronRight,TrendingUp,TrendingDown,ShieldCheck,Pencil,Printer,Code2,LogOut,ExternalLink} from 'lucide-react';
import './styles.css';
import './report-print.css';
import './report-export.css';
import './budget-categories.css';
import './account-actions.css';
import './bills.css';
